def canon_gardien(tag):
    if tag in GARDIEN_ANGLAIS:
        return GARDIEN_ANGLAIS[tag]
    c = canon(tag)
    return SUBIS.get(c, GARDIEN_RENOMME.get(c, c))

def inconnues(tags):
    return sorted((t for t in tags if t not in TAGS))

def sens(tag):
    if tag in SENS:
        return SENS[tag]
    i = TAGS.get(tag, {}).get('issue')
    return 1 if i == 1 else -1 if i == 0 else 0

def info(tag):
    d = TAGS.get(tag, dict(fam='autres', issue=None, fr=tag, en=tag, ar=tag))
    return dict(d, sens=sens(tag))

def table():
    return dict(familles=[dict(cle=c, fr=f, en=e, ar=a) for c, f, e, a in FAMILLES], tags={k: dict(v, sens=sens(k)) for k, v in TAGS.items()})
